      "context": "Over 500 peer-reviewed publications on LLMs in medicine published in 2023 alone"
    },
    {
      "label": "Hallucination Rate",
      "value": "Up to 30%",
      "context": "Studies report LLMs can generate fabricated medical references or inaccurate clinical information in up to 30% of outputs"
    },
    {
      "label": "Global LLM Health Market (projected 2030)",
      "value": "$10.5B",
      "context": "The healthcare LLM market is projected to reach $10.5 billion by 2030"
    }
  ]
}

