import asyncio
import os
from playwright.async_api import async_playwright

async def render_poster():
    html_path = "/app/output/poster-infographic.html"
    output_path = "/app/output/final_poster.png"
    svg_path = "/app/output/poster.svg"
    file_url = f"file://{html_path}"

    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)

        # Use large viewport matching A0 portrait ratio
        vp_w, vp_h = 1200, 1697
        page = await browser.new_page(viewport={"width": vp_w, "height": vp_h})

        console_msgs = []
        page.on("console", lambda msg: console_msgs.append(f"[{msg.type}] {msg.text}"))

        await page.goto(file_url, wait_until="networkidle", timeout=60000)
        await asyncio.sleep(3)

        print("Console output:")
        for m in console_msgs:
            print(f"  {m}")

        # Extract SVG
        svg_data = await page.evaluate("""
            () => {
                const container = document.getElementById('container');
                const svg = container ? container.querySelector('svg') : null;
                if (!svg) return null;
                const clone = svg.cloneNode(true);
                const bbox = svg.getBoundingClientRect();
                return {
                    svg: clone.outerHTML,
                    width: bbox.width,
                    height: bbox.height
                };
            }
        """)

        if not svg_data or not svg_data['svg'] or len(svg_data['svg']) < 200:
            print("ERROR: Could not extract valid SVG")
            await page.screenshot(path="/app/output/debug_screenshot.png", full_page=True)
            print("Debug screenshot saved")
            await browser.close()
            return

        svg_w = svg_data['width']
        svg_h = svg_data['height']
        print(f"SVG rendered size: {svg_w:.0f}x{svg_h:.0f}")

        # Save SVG
        with open(svg_path, 'w') as f:
            f.write(svg_data['svg'])

        # A0 at 200 DPI
        target_w = 6614
        # Maintain SVG aspect ratio but scale to width
        aspect = svg_h / svg_w if svg_w > 0 else 1.414
        target_h = int(target_w * aspect)

        # If the infographic is too short for A0, pad it
        min_a0_h = 9354
        if target_h < min_a0_h:
            target_h = min_a0_h
            # Center SVG vertically on A0 canvas

        print(f"Target: {target_w}x{target_h}")

        # Create page with SVG scaled to target size
        svg_html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  background: #FFFFFF;
  width: {target_w}px;
  height: {target_h}px;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}}
svg {{
  width: {target_w}px;
  height: auto;
  display: block;
}}
</style></head><body>
{svg_data['svg']}
</body></html>"""

        svg_page_path = "/app/output/poster-svg-page.html"
        with open(svg_page_path, 'w') as f:
            f.write(svg_html)

        # Render high-res
        svg_page = await browser.new_page(viewport={"width": target_w, "height": target_h})
        svg_file_url = f"file://{svg_page_path}"
        await svg_page.goto(svg_file_url, wait_until="networkidle", timeout=60000)
        await asyncio.sleep(1)

        await svg_page.screenshot(path=output_path, full_page=False)
        print(f"Poster saved to {output_path}")

        size_mb = os.path.getsize(output_path) / (1024 * 1024)
        from PIL import Image
        img = Image.open(output_path)
        print(f"Final PNG: {img.size[0]}x{img.size[1]} pixels, {size_mb:.1f} MB")

        await browser.close()

asyncio.run(render_poster())

