body {
  font-family: 'Helvetica Neue', 'Arial', 'Noto Sans', system-ui, -apple-system, sans-serif;
  background: #e8ecf1;
  display: flex;
  justify-content: center;
  padding: 20px 0;
}
.poster {
  width: 1600px;
  min-height: 2263px;
  background: var(--white);
