import asyncio
from playwright.async_api import async_playwright

async def debug():
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True, args=['--no-sandbox'])
        page = await browser.new_page(viewport={"width": 1655, "height": 2340})

        errors = []
        page.on("pageerror", lambda err: errors.append(f"PAGE ERROR: {err.message}"))
        page.on("console", lambda msg: None)  # suppress logs

        await page.goto(f"file:///app/output/poster.html", wait_until="networkidle", timeout=30000)
        await asyncio.sleep(1)

        if errors:
            print("Errors found:")
            for e in errors:
                print(f"  {e}")
        else:
            print("No page errors")

        # Check DOM structure of two-col section
        result = await page.evaluate("""
            () => {
                const sections = document.querySelectorAll('.section-col');
                const info = [];
                sections.forEach((s, i) => {
                    const h2 = s.querySelector('h2');
                    const items = s.querySelectorAll('.app-item, .risk-item');
                    const rect = s.getBoundingClientRect();
                    info.push({
                        index: i,
                        heading: h2 ? h2.textContent.trim() : 'none',
                        itemCount: items.length,
                        rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height },
                        firstItemText: items[0] ? items[0].querySelector('h3').textContent.trim() : 'none'
                    });
                });
                return info;
            }
        """)

        for s in result:
            print(f"Column {s['index']}: heading='{s['heading'][:50]}...' items={s['itemCount']} rect=({s['rect']['x']:.0f},{s['rect']['y']:.0f},{s['rect']['w']:.0f},{s['rect']['h']:.0f}) first='{s['firstItemText']}'")

        # Check the two-col container
        two_col = await page.evaluate("""
            () => {
                const tc = document.querySelector('.two-col');
                if (!tc) return null;
                const rect = tc.getBoundingClientRect();
                const style = window.getComputedStyle(tc);
                return {
                    rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height },
                    overflow: style.overflow,
                    display: style.display,
                    gridTemplateColumns: style.gridTemplateColumns
                };
            }
        """)
        print(f"Two-col: rect=({two_col['rect']['x']:.0f},{two_col['rect']['y']:.0f},{two_col['rect']['w']:.0f},{two_col['rect']['h']:.0f}) overflow={two_col['overflow']}")

        await browser.close()

asyncio.run(debug())

